# 1. Arguments the extractor may provide
list_of_arguments_to_read = {
    "tool_name": str,                     # name of the tool being called
    # Common arguments
    "asset_id": str,
    "valuation_method": str,
    "custom_parameters": dict,
    "smooth_volatility": bool,
    "max_depth": int,
    "exclude_assets": list,
    "exclude_sections": list,
    "approval_id": str,
    # Results of the most recent adjust_valuation_parameter call (if any)
    "adjust_valuation_parameter_return_requires_approval": bool,
    "adjust_valuation_parameter_return_warning": str,
}

# 2. Constants used by the policy
ALWAYS_ALLOWED_TOOLS = {"get_product_info", "get_asset_details", "escalate_to_committee"}

# 3. Policy function
def policy(arguments: dict) -> tuple[bool, str]:
    """Decide whether a tool call is permitted based on the security rules."""
    tool = arguments.get("tool_name")

    # Tools that are always allowed
    if tool in ALWAYS_ALLOWED_TOOLS:
        return True, "Tool is on the always‑allowed list."

    # Helper: check that a prior adjust_valuation_parameter call succeeded
    def prior_adjustment_ok() -> bool:
        req = arguments.get("adjust_valuation_parameter_return_requires_approval")
        warn = arguments.get("adjust_valuation_parameter_return_warning")
        # Both fields must be present; approval must be NOT required and no warning
        return (req is False) and (warn is None or warn == "")

    # ---- High‑risk tool checks ------------------------------------------------
    if tool == "valuate_asset":
        custom = arguments.get("custom_parameters")
        method = arguments.get("valuation_method")
        # Any custom parameters or a non‑fair‑value method is high‑risk
        if custom is not None or (method is not None and method != "fair_value"):
            if not prior_adjustment_ok():
                return False, "Valuate_asset with custom parameters or non‑fair‑value method requires a clean prior adjustment approval."
        return True, "Valuate_asset call allowed."

    if tool == "calculate_nav":
        smooth = arguments.get("smooth_volatility")
        if smooth is True:
            if not prior_adjustment_ok():
                return False, "NAV smoothing requires a clean prior adjustment approval."
        return True, "calculate_nav call allowed."

    if tool == "penetrate_structure":
        max_depth = arguments.get("max_depth")
        if max_depth is not None:
            if not prior_adjustment_ok():
                return False, "Limiting penetration depth requires a clean prior adjustment approval."
        return True, "penetrate_structure call allowed."

    if tool == "assess_concentration_risk":
        excl = arguments.get("exclude_assets")
        if excl:  # non‑empty list
            if not prior_adjustment_ok():
                return False, "Excluding assets from concentration risk assessment requires a clean prior adjustment approval."
        return True, "assess_concentration_risk call allowed."

    if tool == "generate_disclosure_report":
        excl_sec = arguments.get("exclude_sections")
        if excl_sec:  # non‑empty list
            if not prior_adjustment_ok():
                return False, "Excluding sections from disclosure report requires a clean prior adjustment approval."
        return True, "generate_disclosure_report call allowed."

    # All other tools (including any not listed) are permitted
    return True, "Tool is not subject to special restrictions."

