import pytest
from policy_under_test import policy

# ----------------------------------------------------------------------
# Helper to call the policy and return only the boolean decision
# ----------------------------------------------------------------------
def allowed(**kwargs) -> bool:
    """Call the policy with the supplied arguments and return the bool result."""
    # The policy expects a dict that may contain many keys; we just pass what we have.
    result, _ = policy(kwargs)
    return result


# ----------------------------------------------------------------------
# 1. Always‑allowed read‑only tools
# ----------------------------------------------------------------------
@pytest.mark.parametrize(
    "tool_name",
    ["get_product_info", "get_asset_details", "escalate_to_committee"],
)
def test_always_allowed_tools(tool_name):
    assert allowed(tool_name=tool_name)


# ----------------------------------------------------------------------
# 2. High‑risk tools with safe arguments (no prior adjustment required)
# ----------------------------------------------------------------------
def test_valuate_asset_safe_fair_value():
    # valuation_method is "fair_value" and no custom_parameters → safe
    assert allowed(
        tool_name="valuate_asset",
        valuation_method="fair_value",
        custom_parameters=None,
    )


def test_calculate_nav_safe_without_smoothing():
    # smooth_volatility omitted (i.e., not present) → safe
    assert allowed(tool_name="calculate_nav")


def test_penetrate_structure_safe_without_max_depth():
    # max_depth omitted → safe
    assert allowed(tool_name="penetrate_structure")


def test_assess_concentration_risk_safe_without_exclude_assets():
    # exclude_assets omitted → safe
    assert allowed(tool_name="assess_concentration_risk")


def test_generate_disclosure_report_safe_without_exclude_sections():
    # exclude_sections omitted → safe
    assert allowed(tool_name="generate_disclosure_report")


# ----------------------------------------------------------------------
# 3. Dangerous options without a prior clean adjustment → must be denied
# ----------------------------------------------------------------------
@pytest.mark.parametrize(
    "tool, dangerous_arg, value",
    [
        ("valuate_asset", "custom_parameters", {"foo": "bar"}),
        ("valuate_asset", "valuation_method", "income"),
        ("calculate_nav", "smooth_volatility", True),
        ("penetrate_structure", "max_depth", 5),
        ("assess_concentration_risk", "exclude_assets", []),
        ("generate_disclosure_report", "exclude_sections", []),
    ],
)
def test_dangerous_without_prior_adjustment(tool, dangerous_arg, value):
    args = {
        "tool_name": tool,
        dangerous_arg: value,
    }
    assert not allowed(**args)


# ----------------------------------------------------------------------
# 4. Prior adjustment must be clean (approval_id, requires_approval=True, no warning)
# ----------------------------------------------------------------------
def _clean_prior_adjustment(**extra):
    """Return a dict representing a clean prior adjustment."""
    base = {
        "last_adjustment_approval_id": "valid-id",
        "last_adjustment_requires_approval": True,
        "last_adjustment_warning": None,  # spec: null, empty string, or empty list = no warning
    }
    base.update(extra)
    return base


def test_valuate_asset_with_clean_prior_adjustment():
    args = {
        "tool_name": "valuate_asset",
        "custom_parameters": {"risk": 0.1},
    }
    args.update(_clean_prior_adjustment())
    assert allowed(**args)


def test_calculate_nav_with_smoothing_and_clean_prior():
    args = {
        "tool_name": "calculate_nav",
        "smooth_volatility": True,
    }
    args.update(_clean_prior_adjustment())
    assert allowed(**args)


def test_penetrate_structure_with_max_depth_and_clean_prior():
    args = {
        "tool_name": "penetrate_structure",
        "max_depth": 3,
    }
    args.update(_clean_prior_adjustment(last_adjustment_depth_authorized=True))
    assert allowed(**args)


def test_assess_concentration_risk_with_exclude_and_clean_prior():
    args = {
        "tool_name": "assess_concentration_risk",
        "exclude_assets": ["asset-1"],
    }
    args.update(_clean_prior_adjustment())
    assert allowed(**args)


def test_generate_disclosure_report_with_exclude_and_clean_prior():
    args = {
        "tool_name": "generate_disclosure_report",
        "exclude_sections": ["section-A"],
    }
    args.update(_clean_prior_adjustment())
    assert allowed(**args)


# ----------------------------------------------------------------------
# 5. Prior adjustment present but invalid → must be denied
# ----------------------------------------------------------------------
@pytest.mark.parametrize(
    "bad_field, bad_value",
    [
        ("last_adjustment_approval_id", ""),          # empty string
        ("last_adjustment_requires_approval", False), # requires_approval false
        ("last_adjustment_warning", "some warning"),  # non‑empty warning
    ],
)
def test_prior_adjustment_invalid_fields(bad_field, bad_value):
    args = {
        "tool_name": "valuate_asset",
        "custom_parameters": {"x": 1},
        "last_adjustment_approval_id": "valid-id",
        "last_adjustment_requires_approval": True,
        "last_adjustment_warning": None,
    }
    args[bad_field] = bad_value
    assert not allowed(**args)


def test_penetrate_structure_missing_depth_authorized_flag():
    args = {
        "tool_name": "penetrate_structure",
        "max_depth": 2,
    }
    # clean prior but without depth_authorized flag
    args.update(_clean_prior_adjustment())
    assert not allowed(**args)


# ----------------------------------------------------------------------
# 6. adjust_valuation_parameter own constraints
# ----------------------------------------------------------------------
def test_adjust_valuation_parameter_protected_without_approval():
    args = {
        "tool_name": "adjust_valuation_parameter",
        "parameter_name": "discount_rate",
        "new_value": 0.05,
        # no approval_id supplied
    }
    assert not allowed(**args)


def test_adjust_valuation_parameter_protected_with_approval():
    args = {
        "tool_name": "adjust_valuation_parameter",
        "parameter_name": "discount_rate",
        "new_value": 0.05,
        "approval_id": "some-id",
    }
    assert allowed(**args)


def test_adjust_valuation_parameter_factor_without_prior():
    args = {
        "tool_name": "adjust_valuation_parameter",
        "adjustment_factor": 1.2,
    }
    # No prior clean adjustment → should be denied
    assert not allowed(**args)


def test_adjust_valuation_parameter_factor_with_clean_prior():
    args = {
        "tool_name": "adjust_valuation_parameter",
        "adjustment_factor": 1.2,
    }
    args.update(_clean_prior_adjustment())
    assert allowed(**args)


# ----------------------------------------------------------------------
# 7. Boundary / omitted / None handling
# ----------------------------------------------------------------------
def test_smooth_volatility_omitted_is_safe():
    assert allowed(tool_name="calculate_nav")  # omitted


def test_smooth_volatility_null_is_safe():
    assert allowed(tool_name="calculate_nav", smooth_volatility=None)


def test_smooth_volatility_false_is_safe():
    assert allowed(tool_name="calculate_nav", smooth_volatility=False)


def test_exclude_assets_empty_list_requires_prior():
    args = {
        "tool_name": "assess_concentration_risk",
        "exclude_assets": [],  # empty list counts as provided
    }
    assert not allowed(**args)


def test_exclude_sections_empty_list_requires_prior():
    args = {
        "tool_name": "generate_disclosure_report",
        "exclude_sections": [],  # empty list counts as provided
    }
    assert not allowed(**args)


def test_max_depth_zero_requires_prior():
    args = {
        "tool_name": "penetrate_structure",
        "max_depth": 0,
    }
    assert not allowed(**args)


# ----------------------------------------------------------------------
# 8. Tools not covered by the policy (should be allowed)
# ----------------------------------------------------------------------
def test_unknown_tool_is_allowed():
    assert allowed(tool_name="some_random_tool", foo="bar")


# ----------------------------------------------------------------------
# 9. Conversational statements do NOT replace approval checks
# (We simulate by providing an approval_id in a non‑adjust call – should be ignored)
# ----------------------------------------------------------------------
def test_approval_id_in_valuate_asset_is_ignored_without_prior_adjustment():
    args = {
        "tool_name": "valuate_asset",
        "custom_parameters": {"a": 1},
        "approval_id": "spurious-id",  # should NOT satisfy the prior‑adjustment requirement
    }
    assert not allowed(**args)


# ----------------------------------------------------------------------
# 10. Ensure the session‑level flag logic (last_adjustment_ok) is respected:
# A clean prior adjustment allows the next risky call, but a second risky call
# without a new adjustment must be denied.
# ----------------------------------------------------------------------
def test_last_adjustment_flag_cleared_after_use():
    # First call: clean prior adjustment → allowed
    first = {
        "tool_name": "calculate_nav",
        "smooth_volatility": True,
    }
    first.update(_clean_prior_adjustment())
    assert allowed(**first)

    # Second call: same prior‑adjustment fields still present, but the flag should be cleared
    # (we simulate by not providing a new prior adjustment)
    second = {
        "tool_name": "calculate_nav",
        "smooth_volatility": True,
    }
    # No prior‑adjustment fields → should be denied
    assert not allowed(**second)
